insert into detective_cases(id, slug, title, title_ar, description, description_ar, case_type, difficulty, age_min, age_max, status, created_by, category, estimated_minutes, briefing, briefing_ar, objective, objective_ar, cover_image_path) values ('52f46cb3-4302-54f2-9c70-559b44e2886b', $q$room-307$q$, $q$The Last Night in Room 307$q$, $q$آخر ليلة في الغرفة 307$q$, $q$A hotel owner is found dead in room 307 of his own Cairo hotel. A knife in a waste bag seems to name the killer, but does it?$q$, $q$مالك فندق فاخر في القاهرة يُعثر عليه مقتولًا في الغرفة 307 داخل فندقه. سكين في كيس قمامة تبدو كأنها تشير إلى القاتل… لكن هل هي الحقيقة؟$q$, 'FULL', 3, 16, 99, 'DRAFT', v_user, $q$جريمة قتل$q$, 30, $q$06:10. Room service found Adel Mansour, owner of the Nile Crown Hotel, dead in room 307. He was staying there the night before a 9:00 board meeting. The hotel is sealed and three people had reason to be near him that night. Search the four locations, send the evidence to the lab, question the suspects and make your accusation. This is a fictional case.$q$, $q$الساعة 6:10 صباحًا. عامل خدمة الغرف وجد عادل منصور، مالك فندق تاج النيل، مقتولًا في الغرفة 307. كان بايت في الفندق ليلة اجتماع مجلس الإدارة الساعة 9. الفندق مقفول، وفيه تلات أشخاص كان عندهم سبب يقربوا منه الليلة دي. افحص الأماكن الأربعة، ابعت الأدلة للمعمل، استجوب المشتبه بهم، وقدّم اتهامك. القضية خيالية بالكامل.$q$, $q$Find who killed Adel Mansour, why, how, and prove it with evidence.$q$, $q$اكتشف مين قتل عادل منصور، وليه، وإزاي، وأثبت ده بالأدلة.$q$, 'demo/detective/room-307/cover.webp') on conflict (id) do nothing;
