insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('6b0ddcd8-645c-5141-beb6-0b906dc0daef', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '29388507-c8b1-5918-9778-996074bfa751', $q$MULTIPLE_CHOICE$q$, $q$إيه اللي نقط الدم في الأوضة والطرقة بتقوله عن السكين؟$q$, $q$إيه اللي نقط الدم في الأوضة والطرقة بتقوله عن السكين؟$q$, $q$[{"id":"a","text":"It was carried from room 307 out to the cart","text_ar":"اتشالت من الأوضة 307 لبره ناحية العربة"},{"id":"b","text":"It was brought from the cart into the room","text_ar":"اتجابت من العربة لجوه الأوضة"},{"id":"c","text":"The victim walked to the corridor himself","text_ar":"الضحية خرج للطرقة بنفسه"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$Drops lead from inside the room to the door: the weapon was carried out.$q$, $q$النقط بتبدأ جوه الأوضة وتكمل في الطرقة لحد العربة: السلاح اتشال لبره بعد الجريمة.$q$, array['b111b343-0293-5c71-ad77-0922f0c24460'::uuid,'96cac31b-0b77-5d8a-9d11-17d55b895e7c'::uuid]::uuid[], 10, -3, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('d2f9d0c1-0fd1-5f1f-ae94-ec0e10684c70', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '29388507-c8b1-5918-9778-996074bfa751', $q$TRUE_FALSE$q$, $q$وجود السكين في كيس قمامة عربة هدى يثبت إنها القاتلة.$q$, $q$وجود السكين في كيس قمامة عربة هدى يثبت إنها القاتلة.$q$, $q$[]$q$::jsonb, $q${"value":"false"}$q$::jsonb, '[]'::jsonb, $q$Dumping the weapon in housekeeping's bag was meant to point at Hoda.$q$, $q$مكان الدليل لوحده مش بيثبت مين حطه. أي حد عدّى في الطرقة كان يقدر يرميها في الكيس.$q$, array['a0b0e786-5ee1-576c-a9d2-ae9edce67f49'::uuid,'52fba34a-bcf2-5573-a69e-1ad258b514af'::uuid]::uuid[], 10, -3, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('c69964a2-2741-5c2d-91cf-29ed661a7c0d', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'eefd7a5e-fea7-5f23-89aa-e595961d9971', $q$MULTIPLE_CHOICE$q$, $q$تقرير جوانتي اللاتكس بيقول إيه؟$q$, $q$تقرير جوانتي اللاتكس بيقول إيه؟$q$, $q$[{"id":"a","text":"Hoda is excluded; the partial profile is consistent with Sherif","text_ar":"هدى مستبعدة، والبصمة الوراثية الجزئية متوافقة مع شريف"},{"id":"b","text":"The gloves prove Hoda was in the room","text_ar":"الجوانتي بيثبت إن هدى كانت في الأوضة"},{"id":"c","text":"No human traces were found","text_ar":"مفيش أي آثار بشرية"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$Hoda wears size S; the gloves were left to suggest a cleaner did it.$q$, $q$النتيجة الجزئية مش دليل إدانة لوحدها، لكنها بتستبعد هدى وبتتوافق مع شريف.$q$, array['9c4b9400-2b8f-5d53-91b7-abf15dc337ae'::uuid]::uuid[], 15, -4, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('264e8510-2140-5524-84d6-4af09bd867c3', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'eefd7a5e-fea7-5f23-89aa-e595961d9971', $q$EVIDENCE_RELATIONSHIP$q$, $q$إيه العلاقة بين كارت HK-02 اللي على الأرض وسجل برمجة الكروت؟$q$, $q$إيه العلاقة بين كارت HK-02 اللي على الأرض وسجل برمجة الكروت؟$q$, $q$[]$q$::jsonb, $q${"from":"ddc7db53-ceed-578a-ab8c-987f06b38b7b","to":"86042052-908d-5928-9e79-bae0bc959ed9","relation":"SUPPORTS"}$q$::jsonb, '[]'::jsonb, $q$HK-02 belongs to housekeeping, but it was re-encoded at 23:52 from the manager's account.$q$, $q$السجل بيقول إن الكارت ده نفسه اتبرمج 23:52 من حساب المدير.$q$, array['ddc7db53-ceed-578a-ab8c-987f06b38b7b'::uuid,'86042052-908d-5928-9e79-bae0bc959ed9'::uuid]::uuid[], 15, -4, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('5b7fcbf9-9a3c-56d9-82b9-a1ba1526c449', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'eefd7a5e-fea7-5f23-89aa-e595961d9971', $q$TRUE_FALSE$q$, $q$الدم على كُم الجاكيت متوافق مع دم الضحية، وده لوحده كفاية عشان نثبت إن صاحب الجاكيت قتله.$q$, $q$الدم على كُم الجاكيت متوافق مع دم الضحية، وده لوحده كفاية عشان نثبت إن صاحب الجاكيت قتله.$q$, $q$[]$q$::jsonb, $q${"value":"false"}$q$::jsonb, '[]'::jsonb, $q$Lab: consistent with the victim's blood, not Sherif's.$q$, $q$التوافق بيربط الجاكيت بالجريمة، لكن الإثبات محتاج أدلة تانية: السجل والكاميرا والكارت.$q$, array['20e48e67-c8e7-5405-97ef-dadd343d08f7'::uuid]::uuid[], 10, -3, 3) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('482233f6-0fff-52d1-8130-079238b2a8a7', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '133e6e66-e47c-54eb-98bf-b2d83cec552f', $q$CONTRADICTION_IDENTIFICATION$q$, $q$أي دليل بيناقض قول شريف إنه مشي 23:30؟$q$, $q$أي دليل بيناقض قول شريف إنه مشي 23:30؟$q$, $q$[{"id":"a","text":"HK-02 encoded from his account at 23:52","text_ar":"HK-02 اتبرمج من حسابه 23:52"},{"id":"b","text":"Hoda's broken card","text_ar":"كارت هدى المكسور"},{"id":"c","text":"The argument at dinner","text_ar":"خناقة العشا"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$23:52 – HK-02 encoded by S.KAMAL, contradicting Sherif's 23:30 departure.$q$, $q$محدش يقدر يبرمج كارت من حساب شريف إلا وهو في الفندق ومسجّل دخول.$q$, array['86042052-908d-5928-9e79-bae0bc959ed9'::uuid]::uuid[], 15, -4, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('7269276b-8b15-5fa4-b355-821e4d99d287', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '133e6e66-e47c-54eb-98bf-b2d83cec552f', $q$MULTIPLE_CHOICE$q$, $q$ليه خناقة طارق مع الضحية مش كفاية عشان نتهمه؟$q$, $q$ليه خناقة طارق مع الضحية مش كفاية عشان نتهمه؟$q$, $q$[{"id":"a","text":"He left at 23:05, an hour before the camera gap","text_ar":"مشي 23:05، قبل فراغ الكاميرا بساعة"},{"id":"b","text":"He has no shares in the hotel","text_ar":"معندوش حصة في الفندق"},{"id":"c","text":"He was the one who called the police","text_ar":"هو اللي بلّغ البوليس"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$The camera was disabled from the manager's admin account.$q$, $q$الخناقة دافع محتمل، لكن التوقيت المستقل (الفاليه والكاميرا) بيخرجه برة وقت الجريمة.$q$, array['ae909243-715f-5fe9-af1f-03afffcbc623'::uuid]::uuid[], 10, -3, 2) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('5a65610d-a650-5522-be2f-2309fe4e1052', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'afbebbf3-9b4e-5696-b2d4-62ea1457faaa', $q$MULTIPLE_CHOICE$q$, $q$رتّب الأحداث من الأقدم للأحدث. اختر الترتيب الصحيح.$q$, $q$رتّب الأحداث من الأقدم للأحدث. اختر الترتيب الصحيح.$q$, $q$[{"id":"a","text":"Third-floor camera switched off → HK-02 re-encoded from the manager's account → Room 307 opened with HK-02 → Knife dumped in the housekeeping bag","text_ar":"كاميرا الدور التالت اتقفلت ← HK-02 اتبرمج من حساب المدير ← الأوضة 307 اتفتحت بـ HK-02 ← السكين اترمت في كيس التدبير المنزلي"},{"id":"b","text":"Third-floor camera switched off → Room 307 opened with HK-02 → Knife dumped in the housekeeping bag → HK-02 re-encoded from the manager's account","text_ar":"كاميرا الدور التالت اتقفلت ← الأوضة 307 اتفتحت بـ HK-02 ← السكين اترمت في كيس التدبير المنزلي ← HK-02 اتبرمج من حساب المدير"},{"id":"c","text":"HK-02 re-encoded from the manager's account → Third-floor camera switched off → Room 307 opened with HK-02 → Knife dumped in the housekeeping bag","text_ar":"HK-02 اتبرمج من حساب المدير ← كاميرا الدور التالت اتقفلت ← الأوضة 307 اتفتحت بـ HK-02 ← السكين اترمت في كيس التدبير المنزلي"},{"id":"d","text":"Knife dumped in the housekeeping bag → Room 307 opened with HK-02 → Third-floor camera switched off → HK-02 re-encoded from the manager's account","text_ar":"السكين اترمت في كيس التدبير المنزلي ← الأوضة 307 اتفتحت بـ HK-02 ← كاميرا الدور التالت اتقفلت ← HK-02 اتبرمج من حساب المدير"}]$q$::jsonb, $q${"option_id":"c"}$q$::jsonb, '[]'::jsonb, $q$23:52 – HK-02 encoded by S.KAMAL, contradicting Sherif's 23:30 departure.$q$, $q$23:52 – برمجة HK-02 من حساب S.KAMAL. ده بيكذب قول شريف إنه مشي 23:30.$q$, array['86042052-908d-5928-9e79-bae0bc959ed9'::uuid,'ae909243-715f-5fe9-af1f-03afffcbc623'::uuid,'ddc7db53-ceed-578a-ab8c-987f06b38b7b'::uuid,'a0b0e786-5ee1-576c-a9d2-ae9edce67f49'::uuid]::uuid[], 15, -4, 1) on conflict (id) do nothing;
insert into detective_questions(id, version_id, stage_id, question_type, prompt, prompt_ar, options, answer_key, accepted_alternatives, explanation, explanation_ar, associated_evidence, points, penalty, position) values ('f4b0b67c-21e0-5f37-b3f2-8efb93549bf2', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'afbebbf3-9b4e-5696-b2d4-62ea1457faaa', $q$FINAL_CONCLUSION$q$, $q$إيه أفضل تفسير لمقتل عادل منصور؟$q$, $q$إيه أفضل تفسير لمقتل عادل منصور؟$q$, $q$[{"id":"a","text":"Sherif re-encoded the master card, cut the camera, killed Adel to hide his fraud and framed housekeeping","text_ar":"شريف برمج الكارت الماستر وقفل الكاميرا وقتل عادل عشان يخبّي الاختلاس، وحاول يلبّسها للتدبير المنزلي"},{"id":"b","text":"Hoda killed Adel over the warning and hid the knife in her cart","text_ar":"هدى قتلت عادل بسبب الإنذار وخبّت السكين في عربيتها"},{"id":"c","text":"Tarek came back after the argument and killed Adel","text_ar":"طارق رجع بعد الخناقة وقتل عادل"}]$q$::jsonb, $q${"option_id":"a"}$q$::jsonb, '[]'::jsonb, $q$Sherif Kamal killed Adel Mansour. Adel had found fake supplier invoices Sherif approved and planned to expose them at the 9:00 board meeting. At 23:52 Sherif re-encoded the housekeeping master card HK-02 from his own account, switched off the third-floor camera at 00:05, entered room 307 at 00:12 and stabbed Adel with a kitchen knife. He wiped it with a towel and dumped it in the housekeeping bag with size-L gloves to frame Hoda. A stain on his jacket cuff is consistent with Adel's blood.$q$, $q$شريف كمال هو اللي قتل عادل منصور. عادل اكتشف فواتير مورّد وهمي شريف كان بيعتمدها، وكان ناوي يكشفها في اجتماع 9 الصبح. الساعة 23:52 شريف برمج كارت التدبير المنزلي الماستر HK-02 من حسابه، وقفل كاميرا الدور التالت 00:05، ودخل الأوضة 307 الساعة 00:12 وطعن عادل بسكينة من المطبخ. مسحها بفوطة ورماها في كيس عربة التدبير المنزلي مع جوانتي مقاس L عشان يلبّسها لهدى. والبقعة على كُم الجاكيت بتاعه متوافقة مع دم عادل.$q$, array['86042052-908d-5928-9e79-bae0bc959ed9'::uuid,'ae909243-715f-5fe9-af1f-03afffcbc623'::uuid,'20e48e67-c8e7-5405-97ef-dadd343d08f7'::uuid,'48b57826-7b10-556b-b4cc-4d6c6ffe5a27'::uuid]::uuid[], 25, -6, 2) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$Sherif Kamal$q$, $q$شريف كمال$q$, $q$مدير الفندق من 6 سنين، وعنده صلاحية أدمن على الكاميرات وبرمجة الكروت.$q$, $q$مدير الفندق من 6 سنين، وعنده صلاحية أدمن على الكاميرات وبرمجة الكروت. كان مسؤول عن المشتريات والمدفوعات. عادل طلب منه ملفات المورّدين قبل الاجتماع بيومين.$q$, $q$مدير الفندق$q$, $q$Hotel manager$q$, $q${"23:30":"قال إنه مشي","23:52":"حسابه برمج كارت HK-02","00:05":"كاميرا الدور التالت اتقفلت من حسابه"}$q$::jsonb, $q$قال إنه قفل مكتبه ومشي 23:30 وروّح على طول.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('1b9b4256-8977-5db7-a6fa-f1c9a6bfd98a', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$Hoda Samir$q$, $q$هدى سمير$q$, $q$مسؤولة عن الدور التالت، وعربتها وكيس القمامة بتاعها اتلقى فيه السكين.$q$, $q$مسؤولة عن الدور التالت، وعربتها وكيس القمامة بتاعها اتلقى فيه السكين. عادل كان اشتكى من تأخير نضافة الأوض الأسبوع اللي فات، وكتب لها إنذار.$q$, $q$مشرفة التدبير المنزلي$q$, $q$Housekeeping supervisor$q$, $q${"22:50":"بلّغت إن كارتها الشخصي اتكسر","23:00":"سلّمت HK-02 للأمن","23:04":"بصمة خروج"}$q$::jsonb, $q$خلّصت شيفتها 23:00، سلّمت كارت العربة HK-02 للأمن، وبصمت خروج 23:04.$q$) on conflict (id) do nothing;
insert into detective_suspects(id, version_id, name, name_ar, description, description_ar, relationship, background, timeline, alibi) values ('04b135d1-bfab-5b42-9c85-3255db31b2e7', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$Tarek Fahmy$q$, $q$طارق فهمي$q$, $q$شريك عادل في الفندق بنسبة 30%، واتخانقوا على العشا قدام الناس.$q$, $q$شريك عادل في الفندق بنسبة 30%، واتخانقوا على العشا قدام الناس. كان عايز يبيع حصته وعادل رافض. عادل قاله على العشا إن فيه فلوس ناقصة وإنه هيعرف مين ورا ده بكرة.$q$, $q$شريك الضحية$q$, $q$Business partner$q$, $q${"22:40":"خناقة مع عادل في المطعم","23:05":"استلم عربيته من الفاليه"}$q$::jsonb, $q$قال إنه خرج من الفندق 23:05 وروّح بعربيته.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('b3430c41-0da4-5bcc-a58c-4f64f092129c', '6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', $q$I locked my office at 23:30 and went straight home. I never came back that night.$q$, $q$قفلت مكتبي 23:30 وروّحت على طول. مارجعتش الفندق خالص الليلة دي.$q$, $q$FALSE$q$, array['86042052-908d-5928-9e79-bae0bc959ed9'::uuid,'ae909243-715f-5fe9-af1f-03afffcbc623'::uuid,'20e48e67-c8e7-5405-97ef-dadd343d08f7'::uuid]::uuid[], $q$حسابه برمج HK-02 الساعة 23:52 وقفل الكاميرا 00:05، والدم على كُمّه متوافق مع دم الضحية.$q$, $q$حسابه برمج HK-02 الساعة 23:52 وقفل الكاميرا 00:05، والدم على كُمّه متوافق مع دم الضحية.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('955b2331-c889-514a-9e3c-c56112adf8d1', '1b9b4256-8977-5db7-a6fa-f1c9a6bfd98a', $q$I finished at 23:00, gave the cart card to security and clocked out. My own card broke earlier.$q$, $q$خلّصت 23:00، سلّمت كارت العربة للأمن وبصمت خروج. وكارتي الشخصي كان اتكسر قبلها.$q$, $q$TRUE$q$, '{}'::uuid[], $q$الكارت المكسور وسجل الأمن بيأكدوا كلامها. الجوانتي مش مقاسها.$q$, $q$الكارت المكسور وسجل الأمن بيأكدوا كلامها. الجوانتي مش مقاسها.$q$) on conflict (id) do nothing;
insert into detective_statements(id, suspect_id, statement, statement_ar, truth_status, conflicting_evidence, admin_explanation, admin_explanation_ar) values ('07e781cc-8065-5e43-961e-5415c6232286', '04b135d1-bfab-5b42-9c85-3255db31b2e7', $q$We argued, yes. I left at 23:05; the valet will tell you. Adel said money was missing and he'd name someone tomorrow.$q$, $q$أيوه اتخانقنا. أنا مشيت 23:05 والفاليه يشهد. عادل قالي إن فيه فلوس ناقصة وإنه هيقول مين بكرة.$q$, $q$TRUE$q$, '{}'::uuid[], $q$خروجه قبل الجريمة بساعة، وكلامه عن الفلوس الناقصة بيشاور على الدافع الحقيقي.$q$, $q$خروجه قبل الجريمة بساعة، وكلامه عن الفلوس الناقصة بيشاور على الدافع الحقيقي.$q$) on conflict (id) do nothing;
