insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('756140f7-fca5-5831-bf6c-a1b338c2f5f5', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '29388507-c8b1-5918-9778-996074bfa751', $q$ابدأ بالمكان اللي اتلقى فيه السلاح، وبعدين اسأل نفسك: مين كان يقدر يفتح باب الأوضة؟$q$, $q$ابدأ بالمكان اللي اتلقى فيه السلاح، وبعدين اسأل نفسك: مين كان يقدر يفتح باب الأوضة؟$q$, '{}'::jsonb, -1, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('38566f95-70fe-5201-a07a-1645e79fe1d1', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'eefd7a5e-fea7-5f23-89aa-e595961d9971', $q$الكارت اللي على الأرض اسمه مكتوب عليه. دوّر على اسمه في غرفة الأمن.$q$, $q$الكارت اللي على الأرض اسمه مكتوب عليه. دوّر على اسمه في غرفة الأمن.$q$, '{}'::jsonb, -2, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('6ff4cc83-15ea-5785-a071-3aff31c2760d', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '133e6e66-e47c-54eb-98bf-b2d83cec552f', $q$قارن الساعة اللي كل واحد قال إنه مشي فيها بالسجلات اللي مالهاش مصلحة تكذب.$q$, $q$قارن الساعة اللي كل واحد قال إنه مشي فيها بالسجلات اللي مالهاش مصلحة تكذب.$q$, '{}'::jsonb, -2, 1) on conflict (id) do nothing;
insert into detective_hints(id, version_id, stage_id, hint_text, hint_text_ar, unlock_rule, penalty, position) values ('4aab2b99-ecd5-5d04-8b12-1750d70fde20', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', 'afbebbf3-9b4e-5696-b2d4-62ea1457faaa', $q$الدافع في المكتب، والدليل المادي على الكرسي، والتوقيت في غرفة الأمن.$q$, $q$الدافع في المكتب، والدليل المادي على الكرسي، والتوقيت في غرفة الأمن.$q$, '{}'::jsonb, -3, 1) on conflict (id) do nothing;
insert into detective_solutions(id, version_id, public_reveal, public_reveal_ar, solution_key, alternative_hypotheses, educational_explanation, educational_explanation_ar) values ('5dc7123c-a9ba-5201-86d4-0d01e9826db5', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$Sherif Kamal killed Adel Mansour. Adel had found fake supplier invoices Sherif approved and planned to expose them at the 9:00 board meeting. At 23:52 Sherif re-encoded the housekeeping master card HK-02 from his own account, switched off the third-floor camera at 00:05, entered room 307 at 00:12 and stabbed Adel with a kitchen knife. He wiped it with a towel and dumped it in the housekeeping bag with size-L gloves to frame Hoda. A stain on his jacket cuff is consistent with Adel's blood.$q$, $q$شريف كمال هو اللي قتل عادل منصور. عادل اكتشف فواتير مورّد وهمي شريف كان بيعتمدها، وكان ناوي يكشفها في اجتماع 9 الصبح. الساعة 23:52 شريف برمج كارت التدبير المنزلي الماستر HK-02 من حسابه، وقفل كاميرا الدور التالت 00:05، ودخل الأوضة 307 الساعة 00:12 وطعن عادل بسكينة من المطبخ. مسحها بفوطة ورماها في كيس عربة التدبير المنزلي مع جوانتي مقاس L عشان يلبّسها لهدى. والبقعة على كُم الجاكيت بتاعه متوافقة مع دم عادل.$q$, $q${"final_question":"f4b0b67c-21e0-5f37-b3f2-8efb93549bf2"}$q$::jsonb, $q$[{"en":"Hoda Samir is the killer.","ar":"هدى سمير هي القاتلة.","why_wrong_en":"Her card was broken, she had returned HK-02 and clocked out at 23:04; the gloves are not her size and the DNA excludes her.","why_wrong_ar":"كارتها كان مكسور وسلّمت HK-02 وبصمت خروج 23:04، والجوانتي مش مقاسها والبصمة الوراثية بتستبعدها."},{"en":"Tarek Fahmy came back and killed him.","ar":"طارق فهمي رجع وقتله.","why_wrong_en":"He left at 23:05 per the valet, and has no access to cameras or card encoding.","why_wrong_ar":"مشي 23:05 حسب الفاليه، ومعندوش صلاحية على الكاميرات ولا على برمجة الكروت."}]$q$::jsonb, $q$No single clue convicts. The bag points at housekeeping, but location alone proves nothing. Independent records (key-card log, camera log, valet, clock-out) fix who could act when; lab results are 'consistent with', not certainty; together they converge on one person.$q$, $q$مفيش دليل واحد لوحده بيدين حد. الكيس بيشاور على التدبير المنزلي، بس مكان الدليل لوحده مش إثبات. السجلات المستقلة (برمجة الكروت، الكاميرا، الفاليه، البصمة) بتحدد مين كان يقدر يعمل إيه وإمتى، ونتايج المعمل بتقول «متوافق» مش «أكيد». لما كل ده يتجمع بيشاور على شخص واحد.$q$) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('e15d85b7-3de4-536d-9994-bfe4a2ca7bbc', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$blood-knife$q$, '52fba34a-bcf2-5573-a69e-1ad258b514af', $q$BLOOD$q$, $q$Blood on the knife$q$, $q$تحليل الدم على السكين$q$, '{}'::uuid[], $q$Human blood consistent with the victim. No usable fingerprints: the handle was wiped or held with gloves.$q$, $q$دم بشري متوافق مع دم الضحية. مفيش بصمات صالحة: المقبض اتمسح أو اتمسك بجوانتي.$q$, $q${"sample_ids":["S-307-01"],"findings_ar":["العينة دم بشري","متوافقة مع عينة الضحية المرجعية","لا توجد بصمات قابلة للمقارنة"],"limitations_ar":"عدم وجود بصمات لا يستبعد أي شخص."}$q$::jsonb, 0, 10, 1) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('543004f2-1e80-552c-94b4-4268a55313c8', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$towel-blood$q$, 'f9e447eb-3225-5a36-b777-50e80bed46a1', $q$BLOOD$q$, $q$Stain on the towel$q$, $q$بقعة الفوطة$q$, '{}'::uuid[], $q$Blood consistent with the victim, smeared as if a blade was wiped. Towel lot code: third-floor housekeeping stock.$q$, $q$دم متوافق مع الضحية، ممسوح كأن حد مسح بيه نصل. كود الدفعة: مخزون التدبير المنزلي للدور التالت.$q$, $q${"sample_ids":["S-307-02"],"findings_ar":["أثر مسح نصل","من مخزون الدور التالت"],"limitations_ar":"مخزون الدور التالت متاح لأي حد عدّى على العربة."}$q$::jsonb, 0, 5, 2) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('d9a60724-d108-548d-a82c-21cc3da24dc8', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$glove-dna$q$, '9c4b9400-2b8f-5d53-91b7-abf15dc337ae', $q$DNA$q$, $q$Skin cells inside the gloves$q$, $q$خلايا جلد جوه الجوانتي$q$, '{}'::uuid[], $q$Partial profile. Hoda Samir is excluded. The partial profile is consistent with Sherif Kamal's reference sample (limited markers).$q$, $q$بصمة وراثية جزئية. هدى سمير مستبعدة. البصمة الجزئية متوافقة مع عينة شريف كمال المرجعية (عدد علامات محدود).$q$, $q${"sample_ids":["S-307-03"],"findings_ar":["هدى سمير: مستبعدة","شريف كمال: متوافق (جزئي)"],"limitations_ar":"النتيجة الجزئية لا تكفي وحدها للإدانة."}$q$::jsonb, 30, 15, 3) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('3c8eb5ed-55f5-5586-95df-1529c9ee75e9', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$card-prints$q$, 'ddc7db53-ceed-578a-ab8c-987f06b38b7b', $q$FINGERPRINT$q$, $q$Prints on master card HK-02$q$, $q$بصمات كارت HK-02$q$, '{}'::uuid[], $q$One partial thumbprint near the chip, consistent with Sherif Kamal on 9 points. Not enough for a positive identification.$q$, $q$بصمة إبهام جزئية جنب الشريحة، متوافقة مع شريف كمال في 9 نقاط. مش كفاية لتحديد قاطع.$q$, $q${"sample_ids":["F-307-01"],"findings_ar":["بصمة جزئية واحدة","9 نقاط توافق مع شريف كمال"],"limitations_ar":"أقل من الحد المطلوب للتحديد القاطع."}$q$::jsonb, 0, 10, 4) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('410cda1b-5e9d-5a5a-8635-1bd66c02663f', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$jacket-blood$q$, '20e48e67-c8e7-5405-97ef-dadd343d08f7', $q$BLOOD$q$, $q$Stain on the jacket cuff$q$, $q$بقعة كُم الجاكيت$q$, '{}'::uuid[], $q$Human blood consistent with the victim; not consistent with Sherif Kamal's own sample.$q$, $q$دم بشري متوافق مع الضحية، ومش متوافق مع عينة شريف كمال نفسه.$q$, $q${"sample_ids":["S-307-04"],"findings_ar":["متوافق مع الضحية","غير متوافق مع صاحب الجاكيت"],"limitations_ar":"يربط الجاكيت بالدم، لا يحدد وقت حدوث البقعة."}$q$::jsonb, 0, 15, 5) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('334cc7c9-327f-5e95-9e15-46e20f742991', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$camera-log$q$, 'ae909243-715f-5fe9-af1f-03afffcbc623', $q$DIGITAL$q$, $q$Camera system audit$q$, $q$فحص نظام الكاميرات$q$, '{}'::uuid[], $q$Camera 3F-02 disabled at 00:05 and re-enabled at 00:35 from the admin account S.KAMAL, logged in at the security room terminal.$q$, $q$كاميرا 3F-02 اتقفلت 00:05 واتفتحت 00:35 من حساب الأدمن S.KAMAL، من جهاز غرفة الأمن.$q$, $q${"sample_ids":["D-307-01"],"findings_ar":["00:05 إيقاف","00:35 تشغيل","الحساب: S.KAMAL"],"limitations_ar":"السجل يثبت الحساب المستخدم، والربط بالشخص يحتاج أدلة أخرى."}$q$::jsonb, 0, 15, 6) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('45e325e2-9630-5c80-bd89-b7d0e6189f50', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$encoder-log$q$, '86042052-908d-5928-9e79-bae0bc959ed9', $q$DOCUMENT$q$, $q$Key-card encoder log$q$, $q$سجل جهاز برمجة الكروت$q$, '{}'::uuid[], $q$HK-02 was returned at 23:00 and re-encoded at 23:52 by S.KAMAL. HK-02 then opened room 307 at 00:12.$q$, $q$HK-02 اترجع للأمن 23:00 واتبرمج تاني 23:52 من S.KAMAL. وبعدها فتح الأوضة 307 الساعة 00:12.$q$, $q${"sample_ids":["D-307-02"],"findings_ar":["23:00 تسليم HK-02","23:52 إعادة برمجة – S.KAMAL","00:12 فتح 307"],"limitations_ar":"لا يوجد."}$q$::jsonb, 0, 15, 7) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('0b50cb05-f773-50a0-9ca8-4eac35a5ff81', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$time-of-death$q$, null, $q$TIME_OF_DEATH$q$, $q$Medical examiner summary$q$, $q$ملخص الطبيب الشرعي$q$, '{}'::uuid[], $q$Estimated time of death between 00:00 and 01:00. A single stab wound; no signs of a long struggle.$q$, $q$وقت الوفاة التقريبي بين 00:00 و 01:00. طعنة واحدة ومفيش علامات مقاومة طويلة.$q$, $q${"sample_ids":["ME-307"],"findings_ar":["نافذة الوفاة 00:00–01:00","طعنة واحدة"],"limitations_ar":"تقدير بهامش ساعة."}$q$::jsonb, 0, 5, 8) on conflict (id) do nothing;
insert into detective_lab_procedures(id, version_id, procedure_key, evidence_id, exam_type, title, title_ar, requires_evidence, result, result_ar, report, release_seconds, points, position) values ('6280a936-b58e-5460-9e9c-dfc204238bbc', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', $q$ledger-audit$q$, '48b57826-7b10-556b-b4cc-4d6c6ffe5a27', $q$DOCUMENT$q$, $q$Ledger comparison$q$, $q$مقارنة الدفاتر$q$, '{}'::uuid[], $q$EGP 4.2M paid to 'Delta Supplies', which has no registration. Every invoice was approved by Sherif Kamal.$q$, $q$4.2 مليون جنيه اتدفعوا لـ«دلتا للتوريدات» ومالهاش سجل تجاري. كل الفواتير معتمدة من شريف كمال.$q$, $q${"sample_ids":["D-307-03"],"findings_ar":["مورّد غير مسجل","اعتماد: شريف كمال"],"limitations_ar":"يثبت الدافع، لا يثبت القتل."}$q$::jsonb, 0, 10, 9) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('68c04663-168a-587d-a6c5-574e19368d5d', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', '86042052-908d-5928-9e79-bae0bc959ed9', $q$Fine… I came back for a file. I encoded a card to check a room, nothing more.$q$, $q$طيب… رجعت آخد ملف. برمجت كارت أبص بيه على أوضة، مش أكتر.$q$, true, 15) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('c184bfd0-f603-5638-85a2-78a9afcfc083', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', '20e48e67-c8e7-5405-97ef-dadd343d08f7', $q$I cut my hand on a frame last week.$q$, $q$اتعورت في إيدي من برواز الأسبوع اللي فات.$q$, true, 15) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('b6883c1f-0163-5585-ae3a-b58341b7e1f9', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', '48b57826-7b10-556b-b4cc-4d6c6ffe5a27', $q$Accounting mistakes. Adel liked to make a drama of everything.$q$, $q$غلطات محاسبة. عادل كان بيحب يعمل من كل حاجة مشكلة.$q$, false, 5) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('50a17366-4546-5df0-959b-fd91014d4b68', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', 'ae909243-715f-5fe9-af1f-03afffcbc623', $q$Cameras go off all the time in this old building.$q$, $q$الكاميرات بتفصل على طول في المبنى القديم ده.$q$, true, 10) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('eded7e2c-62cb-5ed5-a18d-6d3f7800b473', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '1b9b4256-8977-5db7-a6fa-f1c9a6bfd98a', '9c4b9400-2b8f-5d53-91b7-abf15dc337ae', $q$Those are size L. I wear small – look at my locker.$q$, $q$دي مقاس L. أنا بلبس سمول، شوفوا اللوكر بتاعي.$q$, false, 10) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('38735cbc-11fe-5294-aec1-7fbd44239708', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '1b9b4256-8977-5db7-a6fa-f1c9a6bfd98a', 'ddc7db53-ceed-578a-ab8c-987f06b38b7b', $q$I handed HK-02 to security at 11. Someone took it after me.$q$, $q$أنا سلّمت HK-02 للأمن الساعة 11. حد أخده بعدي.$q$, false, 10) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('f0eaec9a-903a-56aa-aac1-bca56544002d', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '1b9b4256-8977-5db7-a6fa-f1c9a6bfd98a', 'a0b0e786-5ee1-576c-a9d2-ae9edce67f49', $q$Anyone passing can throw something in that bag. I was home by then.$q$, $q$أي حد معدّي يقدر يرمي حاجة في الكيس ده. أنا كنت في البيت ساعتها.$q$, false, 5) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('1fdc5b65-3175-53d4-9ccf-20030a61c746', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '04b135d1-bfab-5b42-9c85-3255db31b2e7', '48b57826-7b10-556b-b4cc-4d6c6ffe5a27', $q$So that's the missing money. Adel said he'd name someone at the meeting.$q$, $q$يبقى دي الفلوس الناقصة. عادل قال إنه هيقول الاسم في الاجتماع.$q$, false, 10) on conflict (id) do nothing;
insert into detective_confrontations(id, version_id, suspect_id, evidence_id, response, response_ar, reveals_contradiction, points) values ('a597a2cb-a9da-5a79-b0ab-c84866313d11', 'bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '04b135d1-bfab-5b42-9c85-3255db31b2e7', '52fba34a-bcf2-5573-a69e-1ad258b514af', $q$I was gone by eleven. Ask the valet.$q$, $q$أنا كنت مشيت قبل 11. اسألوا الفاليه.$q$, false, 5) on conflict (id) do nothing;
insert into detective_verdict_criteria(version_id, suspect_id, motive_options, motive_answer, method_options, method_answer, key_evidence, timeline_order, weights) values ('bd6c4846-fdd5-50f2-9e92-1fee0c95657b', '6b6fae1a-f6eb-5fa4-a624-9cc25a00bb67', $q$[{"id":"fraud","text":"To stop Adel exposing his embezzlement","text_ar":"عشان يمنع عادل يكشف الاختلاس"},{"id":"warning","text":"Revenge for a written warning","text_ar":"انتقام من إنذار مكتوب"},{"id":"shares","text":"A dispute over selling shares","text_ar":"خلاف على بيع الحصة"},{"id":"robbery","text":"Robbery","text_ar":"سرقة"}]$q$::jsonb, $q$fraud$q$, $q$[{"id":"masterkey-knife","text":"Entered with a re-encoded master card and stabbed him with a kitchen knife","text_ar":"دخل بكارت ماستر متبرمج من جديد وطعنه بسكينة مطبخ"},{"id":"invited-in","text":"Was let in by the victim and argued","text_ar":"الضحية فتح له الباب واتخانقوا"},{"id":"balcony","text":"Came in through the balcony","text_ar":"دخل من البلكونة"}]$q$::jsonb, $q$masterkey-knife$q$, array['86042052-908d-5928-9e79-bae0bc959ed9'::uuid,'ae909243-715f-5fe9-af1f-03afffcbc623'::uuid,'20e48e67-c8e7-5405-97ef-dadd343d08f7'::uuid,'ddc7db53-ceed-578a-ab8c-987f06b38b7b'::uuid,'48b57826-7b10-556b-b4cc-4d6c6ffe5a27'::uuid]::uuid[], array[$q$card_encoded$q$,$q$camera_off$q$,$q$room_entered$q$,$q$knife_dumped$q$]::text[], $q${"suspect":40,"motive":15,"method":15,"evidence":20,"timeline":10}$q$::jsonb) on conflict (version_id) do nothing;
